CREATE TABLE oa_department (id BIGINT PRIMARY KEY AUTO_INCREMENT, code VARCHAR(32) NOT NULL UNIQUE, name VARCHAR(64) NOT NULL, sort_order INT NOT NULL DEFAULT 0, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE oa_user (id BIGINT PRIMARY KEY AUTO_INCREMENT, username VARCHAR(32) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL, full_name VARCHAR(50) NOT NULL, email VARCHAR(100), phone VARCHAR(20), position VARCHAR(50), role VARCHAR(20) NOT NULL, enabled BIT NOT NULL DEFAULT 1, department_id BIGINT, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, CONSTRAINT fk_user_department FOREIGN KEY (department_id) REFERENCES oa_department(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE oa_notice (id BIGINT PRIMARY KEY AUTO_INCREMENT, title VARCHAR(120) NOT NULL, content TEXT NOT NULL, publisher VARCHAR(50) NOT NULL, publish_time DATETIME(6) NOT NULL, pinned BIT NOT NULL DEFAULT 0, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE oa_attendance (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT NOT NULL, work_date DATE NOT NULL, check_in_time DATETIME(6), check_out_time DATETIME(6), status VARCHAR(20) NOT NULL, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, UNIQUE KEY uk_attendance_user_date(user_id, work_date), CONSTRAINT fk_attendance_user FOREIGN KEY (user_id) REFERENCES oa_user(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE oa_leave_request (id BIGINT PRIMARY KEY AUTO_INCREMENT, applicant_id BIGINT NOT NULL, leave_type VARCHAR(20) NOT NULL, start_time DATETIME(6) NOT NULL, end_time DATETIME(6) NOT NULL, duration_days DECIMAL(5,1) NOT NULL, reason VARCHAR(500) NOT NULL, status VARCHAR(20) NOT NULL, approver_comment VARCHAR(500), approver_name VARCHAR(50), approved_at DATETIME(6), created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, INDEX idx_leave_status(status), CONSTRAINT fk_leave_applicant FOREIGN KEY (applicant_id) REFERENCES oa_user(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE oa_todo_task (id BIGINT PRIMARY KEY AUTO_INCREMENT, assignee_id BIGINT NOT NULL, title VARCHAR(120) NOT NULL, description VARCHAR(500), due_date DATE, priority VARCHAR(20) NOT NULL, completed BIT NOT NULL DEFAULT 0, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, INDEX idx_task_assignee_completed(assignee_id, completed), CONSTRAINT fk_task_assignee FOREIGN KEY (assignee_id) REFERENCES oa_user(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
